def parse_json(text: str) -> object:
    n = len(text)
    pos = 0

    _HEX = frozenset('0123456789abcdefABCDEF')

    def _skip_ws():
        nonlocal pos
        while pos < n and text[pos] in ' \t\n\r':
            pos += 1

    def _parse_string():
        nonlocal pos
        pos += 1
        chars = []
        while pos < n:
            c = text[pos]
            if c == '"':
                pos += 1
                return ''.join(chars)
            if c == '\\':
                pos += 1
                if pos >= n:
                    raise ValueError("unterminated escape")
                c2 = text[pos]
                if c2 == '"':
                    chars.append('"'); pos += 1
                elif c2 == '\\':
                    chars.append('\\'); pos += 1
                elif c2 == '/':
                    chars.append('/'); pos += 1
                elif c2 == 'b':
                    chars.append('\b'); pos += 1
                elif c2 == 'f':
                    chars.append('\f'); pos += 1
                elif c2 == 'n':
                    chars.append('\n'); pos += 1
                elif c2 == 'r':
                    chars.append('\r'); pos += 1
                elif c2 == 't':
                    chars.append('\t'); pos += 1
                elif c2 == 'u':
                    pos += 1
                    if pos + 4 > n:
                        raise ValueError("truncated \\u escape")
                    h = text[pos:pos + 4]
                    if not all(ch in _HEX for ch in h):
                        raise ValueError("invalid \\u escape")
                    cp = int(h, 16)
                    pos += 4
                    if 0xD800 <= cp <= 0xDBFF:
                        if pos + 6 > n or text[pos] != '\\' or text[pos + 1] != 'u':
                            raise ValueError("lone high surrogate")
                        pos += 2
                        if pos + 4 > n:
                            raise ValueError("truncated \\u escape")
                        h2 = text[pos:pos + 4]
                        if not all(ch in _HEX for ch in h2):
                            raise ValueError("invalid \\u escape")
                        cp2 = int(h2, 16)
                        pos += 4
                        if not (0xDC00 <= cp2 <= 0xDFFF):
                            raise ValueError("invalid surrogate pair")
                        cp = 0x10000 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00)
                    elif 0xDC00 <= cp <= 0xDFFF:
                        raise ValueError("lone low surrogate")
                    chars.append(chr(cp))
                else:
                    raise ValueError("invalid escape character")
            elif ord(c) < 0x20:
                raise ValueError("unescaped control character")
            else:
                chars.append(c)
                pos += 1
        raise ValueError("unterminated string")

    def _parse_number():
        nonlocal pos
        start = pos
        if text[pos] == '-':
            pos += 1
        if pos >= n:
            raise ValueError("invalid number")
        if text[pos] == '0':
            pos += 1
        elif '1' <= text[pos] <= '9':
            pos += 1
            while pos < n and '0' <= text[pos] <= '9':
                pos += 1
        else:
            raise ValueError("invalid number")
        is_float = False
        if pos < n and text[pos] == '.':
            is_float = True
            pos += 1
            if pos >= n or not ('0' <= text[pos] <= '9'):
                raise ValueError("invalid number")
            while pos < n and '0' <= text[pos] <= '9':
                pos += 1
        if pos < n and text[pos] in 'eE':
            is_float = True
            pos += 1
            if pos < n and text[pos] in '+-':
                pos += 1
            if pos >= n or not ('0' <= text[pos] <= '9'):
                raise ValueError("invalid number")
            while pos < n and '0' <= text[pos] <= '9':
                pos += 1
        s = text[start:pos]
        return float(s) if is_float else int(s)

    def _parse_literal(expected, value):
        nonlocal pos
        end = pos + len(expected)
        if pos + len(expected) > n or text[pos:end] != expected:
            raise ValueError("invalid literal")
        pos = end
        return value

    # Iterative state machine with explicit stack to support deep nesting.
    # Stack entries: [is_object, data, key]
    #   array:  [False, list, None]
    #   object: [True,  dict, current_key]
    #
    # States:
    #   0 EXPECT_VALUE     - parse a value, then place it
    #   1 ARR_START        - just opened [, expect value or ]
    #   2 ARR_AFTER_VALUE  - after value in array, expect , or ]
    #   3 OBJ_START        - just opened {, expect key or }
    #   4 OBJ_EXPECT_COLON - after key, expect :
    #   5 OBJ_AFTER_VALUE  - after value in object, expect , or }
    #   6 OBJ_EXPECT_KEY   - after comma in object, expect key
    #   7 DONE             - top-level value obtained

    stack = []
    state = 0
    val = None
    result = None

    while True:
        if state == 0:
            _skip_ws()
            if pos >= n:
                raise ValueError("unexpected end of input")
            c = text[pos]
            if c == '{':
                pos += 1
                stack.append([True, {}, None])
                state = 3
            elif c == '[':
                pos += 1
                stack.append([False, [], None])
                state = 1
            elif c == '"':
                val = _parse_string()
                state = -1
            elif c == 't':
                val = _parse_literal('true', True)
                state = -1
            elif c == 'f':
                val = _parse_literal('false', False)
                state = -1
            elif c == 'n':
                val = _parse_literal('null', None)
                state = -1
            elif c == '-' or '0' <= c <= '9':
                val = _parse_number()
                state = -1
            else:
                raise ValueError("unexpected character")
            if state == -1:
                if not stack:
                    result = val
                    state = 7
                elif not stack[-1][0]:
                    stack[-1][1].append(val)
                    state = 2
                else:
                    key = stack[-1][2]
                    if key in stack[-1][1]:
                        raise ValueError("duplicate key")
                    stack[-1][1][key] = val
                    state = 5

        elif state == 1:
            _skip_ws()
            if pos < n and text[pos] == ']':
                pos += 1
                val = stack.pop()[1]
                state = -1
            else:
                state = 0
            if state == -1:
                if not stack:
                    result = val
                    state = 7
                elif not stack[-1][0]:
                    stack[-1][1].append(val)
                    state = 2
                else:
                    key = stack[-1][2]
                    if key in stack[-1][1]:
                        raise ValueError("duplicate key")
                    stack[-1][1][key] = val
                    state = 5

        elif state == 2:
            _skip_ws()
            if pos < n and text[pos] == ',':
                pos += 1
                state = 0
            elif pos < n and text[pos] == ']':
                pos += 1
                val = stack.pop()[1]
                state = -1
            else:
                raise ValueError("expected ',' or ']'")
            if state == -1:
                if not stack:
                    result = val
                    state = 7
                elif not stack[-1][0]:
                    stack[-1][1].append(val)
                    state = 2
                else:
                    key = stack[-1][2]
                    if key in stack[-1][1]:
                        raise ValueError("duplicate key")
                    stack[-1][1][key] = val
                    state = 5

        elif state == 3:
            _skip_ws()
            if pos < n and text[pos] == '}':
                pos += 1
                val = stack.pop()[1]
                state = -1
            elif pos < n and text[pos] == '"':
                stack[-1][2] = _parse_string()
                state = 4
            else:
                raise ValueError("expected key or '}'")
            if state == -1:
                if not stack:
                    result = val
                    state = 7
                elif not stack[-1][0]:
                    stack[-1][1].append(val)
                    state = 2
                else:
                    key = stack[-1][2]
                    if key in stack[-1][1]:
                        raise ValueError("duplicate key")
                    stack[-1][1][key] = val
                    state = 5

        elif state == 4:
            _skip_ws()
            if pos < n and text[pos] == ':':
                pos += 1
                state = 0
            else:
                raise ValueError("expected ':'")

        elif state == 5:
            _skip_ws()
            if pos < n and text[pos] == ',':
                pos += 1
                state = 6
            elif pos < n and text[pos] == '}':
                pos += 1
                val = stack.pop()[1]
                state = -1
            else:
                raise ValueError("expected ',' or '}'")
            if state == -1:
                if not stack:
                    result = val
                    state = 7
                elif not stack[-1][0]:
                    stack[-1][1].append(val)
                    state = 2
                else:
                    key = stack[-1][2]
                    if key in stack[-1][1]:
                        raise ValueError("duplicate key")
                    stack[-1][1][key] = val
                    state = 5

        elif state == 6:
            _skip_ws()
            if pos < n and text[pos] == '"':
                stack[-1][2] = _parse_string()
                state = 4
            else:
                raise ValueError("expected key")

        elif state == 7:
            _skip_ws()
            if pos < n:
                raise ValueError("trailing characters")
            return result
